mapper.select:
select SEQNO, FINPROD_ID, FINPROD_NAME, STOCK_BORDSTTUS, STOCK_ID, COMP_ORG, MARKET_MULTI, COMP_ORGNAME, COMP_STOCKID, FINPROD_PROIT, FINPROD_NETASSET, SMOOTHSECTION, BINTREE_STEP, CURVE_CODE from MOD_BINTREE_CONFIG where 1=1
AND (FINPROD_ID IN
null) OR FINPROD_ID in (
#{item}
)

SELECT A.FINPROD_ID FINPROD_ID, A.FINPROD_ABBR FINPROD_ABBR, A.FINPROD_MARKET_ID FINPROD_MARKET_ID, A.VDATE VDATE, A.MDATE MDATE, A.ISSUER ISSUER, A.FINANCIER FINANCIER, A.SPONSOR SPONSOR, A.IS_SUS IS_SUS, A.IS_RIGHT IS_RIGHT, A.CON_FINPROD_ID CON_FINPROD_ID, A.CON_VDATE CON_VDATE, A.CON_PRICE CON_PRICE, A.COUPON_SPECIES COUPON_SPECIES, A.ACTUAL_CREDIT_PROVID ACTUAL_CREDIT_PROVID, A.ASSET_ONE ASSET_ONE, A.ASSET_TWO ASSET_TWO, A.ASSET_THREE ASSET_THREE, A.ASSET_FOUR ASSET_FOUR, A.ASSET_FIVE ASSET_FIVE, A.ISSUER_FIN_LICENCE ISSUER_FIN_LICENCE, A.FINANCIER_FIN_LICENCE FINANCIER_FIN_LICENCE, A.SPONSOR_FIN_LICENCE SPONSOR_FIN_LICENCE, A.ACTUAL_CREDIT_FIN_LICENCE ACTUAL_CREDIT_FIN_LICENCE, A.MODYORN MODYORN, A.ISSUE_PRICE ISSUE_PRICE, B.LAST_TRADE_IN_DATE LAST_TRADE_IN_DATE, B.LAST_TRADE_AVG_PRICE LAST_TRADE_AVG_PRICE, B.LAST_TRADE_NET_PRICE LAST_TRADE_NET_PRICE FROM (SELECT A.FINPROD_ID as FINPROD_ID, A.FINPROD_ABBR as FINPROD_ABBR, A.TRADE_MARKET as TRADE_MARKET, A.FINPROD_MARKET_ID as FINPROD_MARKET_ID, A.VDATE as VDATE, A.MDATE as MDATE, A.ISSUER as ISSUER, A.FINANCIER as FINANCIER, A.SPONSOR as SPONSOR, A.IS_SUS as IS_SUS, A.IS_RIGHT as IS_RIGHT, F.CON_FINPROD_ID as CON_FINPROD_ID, F.CON_SHARE_ID as CON_SHARE_ID, F.CON_VDATE as CON_VDATE, F.CON_PRICE as CON_PRICE, G.ACTUAL_CREDIT_PROVID as ACTUAL_CREDIT_PROVID, H.TYPE_8 as ASSET_ONE, H.TYPE_9 as ASSET_TWO, H.TYPE_10 as ASSET_THREE, H.TYPE_11 as ASSET_FOUR, H.TYPE_12 as ASSET_FIVE, B.IS_FIN_LICENCE as ISSUER_FIN_LICENCE, C.IS_FIN_LICENCE as FINANCIER_FIN_LICENCE, D.IS_FIN_LICENCE as SPONSOR_FIN_LICENCE, E.IS_FIN_LICENCE as ACTUAL_CREDIT_FIN_LICENCE, A.COUPON_SPECIES as COUPON_SPECIES, A.ISSUE_PRICE as ISSUE_PRICE, M.IS_LIMITS as IS_LIMITS, A.ISSUE_AMT AS ISSUE_AMT, CASE WHEN (M.IS_RATE_ADJUST = 'Y' AND A8.CT > 0 ) THEN 'Y' ELSE 'N' END IS_AUTHORITY, CASE WHEN (A1.FINPROD_ID IS NOT NULL OR A2.SEC_DETAIL_TYPE IS NOT NULL OR A4.SEC_TYPE IS NOT NULL) THEN 'Y' ELSE 'N' END MODYORN FROM FIN_PRODUCT A INNER JOIN FIN_PRODUCT_TYPE H ON A.FINPROD_ID = H.FINPROD_ID AND H.BRANCH = 0 LEFT JOIN FIN_PRODUCT_ADD M ON A.FINPROD_ID = M.FINPROD_ID LEFT JOIN FIN_PRODUCT_CONVERTIBLE F ON A.FINPROD_ID = F.FINPROD_ID LEFT JOIN PA_FIN_PRODUCT G ON A.FINPROD_ID = G.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO_ADD B ON A.ISSUER = B.CUSTOMER_ID LEFT JOIN MST_CUSTOMER_INFO_ADD C ON A.FINANCIER = C.CUSTOMER_ID LEFT JOIN MST_CUSTOMER_INFO_ADD D ON A.SPONSOR = D.CUSTOMER_ID LEFT JOIN MST_CUSTOMER_INFO_ADD E ON G.ACTUAL_CREDIT_PROVID = E.CUSTOMER_ID LEFT JOIN ( SELECT DISTINCT FINPROD_ID FROM BOK_VAL_SCHEME_DETAIL_SPECIAL WHERE VALUATION_PRICE = 'MOD' ) A1 ON A.FINPROD_ID = A1.FINPROD_ID LEFT JOIN ( SELECT DISTINCT SEC_DETAIL_TYPE FROM BOK_VAL_SCHEME_DETAIL WHERE VALUATION_PRICE = 'MOD'AND SEC_DETAIL_TYPE IS NOT NULL) A2 ON H.TYPE_1 = A2.SEC_DETAIL_TYPE LEFT JOIN ( SELECT DISTINCT (CASE WHEN SEC_TYPE = '01' THEN 'F01' ELSE 'F06'END ) SEC_TYPE FROM BOK_VAL_SCHEME_DETAIL WHERE VALUATION_PRICE = 'MOD'AND SEC_DETAIL_TYPE IS NULL) A4 ON H.TYPE_8 = A4.SEC_TYPE LEFT JOIN ( SELECT FINPROD_ID,COUNT(1) AS CT FROM FIN_EXERCISE_PLAN PLAN WHERE EXERCISE_TYPE = '01' GROUP BY FINPROD_ID ) A8 ON H.FINPROD_ID = A8.FINPROD_ID WHERE A.FINPROD_TYPE2 IN ('F01','F18') )A LEFT JOIN (SELECT C.FINPROD_ID, SUM(C.FPRICE_AMT) / SUM(C.SHARE_AMT) AS LAST_TRADE_AVG_PRICE, SUM(C.CPRICE_AMT) / SUM(C.SHARE_AMT) AS LAST_TRADE_NET_PRICE, D.LAST_TRADE_IN_DATE FROM (SELECT NVL(A.TOTLE_TRADE_ID,A.TRADE_ID) AS TOTLE_TRADE_ID, A.FINPROD_ID AS FINPROD_ID, A.FINPROD_TYPE2 AS FINPROD_TYPE2, A.PS AS PS, abs(A.FPRICE_AMT) AS FPRICE_AMT, abs(A.UNIT_FPRICE) AS UNIT_FPRICE, abs(A.CPRICE_AMT) AS CPRICE_AMT, abs(A.UNIT_CPRICE) AS UNIT_CPRICE, abs(A.TRADE_AMT) AS TRADE_AMT, abs(A.PRIN_AMT) AS PRIN_AMT, abs(A.SHARE_AMT) AS SHARE_AMT, A.INV_AIM AS INV_AIM, A.YIELD AS YIELD, A.SETTLE_DATE AS SETTLE_DATE, A.TRADE_DATE AS TRADE_DATE, A.MDATE AS MDATE, A.IS_CLEAN AS IS_CLEAN, P.PORTFOLIO_ID AS PORTFOLIO_ID, C.FINPROD_ID AS PROD_ID, C.FINPROD_ABBR AS PROD_NAME FROM TRD_PRODUCT_DEAL A INNER JOIN PTL_TRADE B ON A.TRADE_ID = B.BUSI_NO INNER JOIN PTL_PORTFOLIO P ON B.PORTFOLIO_ID = P.PORTFOLIO_ID AND P.INVEST_YESORNO = 'Y' LEFT JOIN FIN_PRODUCT C ON (c.FINPROD_MARKET_ID = P.PORTFOLIO_ID or c.FINPROD_MARKET_ID = P.PARENT_PORTFOLIO_ID) AND C.FINPROD_TYPE2 = 'F16' where A.PS IN ('T01', 'T02', 'T03', 'T39', 'T22', 'T23', 'T07', 'T08', 'T09') AND A.IS_CANCEL = 'N' AND A.TRADE_STATUS = '01' AND A.FINPROD_TYPE2 IN ('F01', 'F18' ))C INNER JOIN (SELECT FINPROD_ID, MAX(SETTLE_DATE) AS LAST_TRADE_IN_DATE FROM (SELECT NVL(A.TOTLE_TRADE_ID,A.TRADE_ID) AS TOTLE_TRADE_ID, A.FINPROD_ID AS FINPROD_ID, A.FINPROD_TYPE2 AS FINPROD_TYPE2, A.PS AS PS, abs(A.FPRICE_AMT) AS FPRICE_AMT, abs(A.UNIT_FPRICE) AS UNIT_FPRICE, abs(A.CPRICE_AMT) AS CPRICE_AMT, abs(A.UNIT_CPRICE) AS UNIT_CPRICE, abs(A.TRADE_AMT) AS TRADE_AMT, abs(A.PRIN_AMT) AS PRIN_AMT, abs(A.SHARE_AMT) AS SHARE_AMT, A.INV_AIM AS INV_AIM, A.YIELD AS YIELD, A.SETTLE_DATE AS SETTLE_DATE, A.TRADE_DATE AS TRADE_DATE, A.MDATE AS MDATE, A.IS_CLEAN AS IS_CLEAN, P.PORTFOLIO_ID AS PORTFOLIO_ID, C.FINPROD_ID AS PROD_ID, C.FINPROD_ABBR AS PROD_NAME FROM TRD_PRODUCT_DEAL A INNER JOIN PTL_TRADE B ON A.TRADE_ID = B.BUSI_NO INNER JOIN PTL_PORTFOLIO P ON B.PORTFOLIO_ID = P.PORTFOLIO_ID AND P.INVEST_YESORNO = 'Y' LEFT JOIN FIN_PRODUCT C ON (c.FINPROD_MARKET_ID = P.PORTFOLIO_ID or c.FINPROD_MARKET_ID = P.PARENT_PORTFOLIO_ID) AND C.FINPROD_TYPE2 = 'F16' where A.PS IN ('T01', 'T02', 'T03', 'T39', 'T22', 'T23', 'T07', 'T08', 'T09') AND A.IS_CANCEL = 'N' AND A.TRADE_STATUS = '01' AND A.FINPROD_TYPE2 IN ('F01', 'F18' )) WHERE SETTLE_DATE <= #{searchDate,jdbcType=DATE} AND PS = 'T01' GROUP BY FINPROD_ID) D ON C.FINPROD_ID = D.FINPROD_ID AND C.SETTLE_DATE = D.LAST_TRADE_IN_DATE AND C.PS = 'T01' GROUP BY C.FINPROD_ID, D.LAST_TRADE_IN_DATE) B ON A.FINPROD_ID = B.FINPROD_ID WHERE EXISTS (SELECT 1 FROM (select A.FINPROD_ID, A.CDATE, A.INV_AIM, SUM(A.AMOUNT) AMOUNT from PTL_SEC_POSITION A INNER JOIN PTL_PORTFOLIO C ON A.PORTFOLIO_ID = C.PORTFOLIO_ID AND C.INVEST_YESORNO = 'Y' INNER JOIN FIN_PRODUCT B ON A.FINPROD_ID = B.FINPROD_ID AND B.FINPROD_TYPE2 IN ('F01', 'F18') where A.HODING_TYPE = '03' GROUP BY A.FINPROD_ID, A.CDATE, A.INV_AIM) M WHERE A.FINPROD_ID = M.FINPROD_ID AND M.CDATE = #{searchDate,jdbcType=DATE} AND M.AMOUNT > 0) AND A.MODYORN = 'Y'
AND A.FINPROD_ID IN(
#{item}
)
AND A.ASSET_FIVE IN(
#{item}
)
